            introduction = "जात र धर्मको पर्खाल भत्काएर प्रेम विवाह गर्नु मात्र पर्याप्त हुँदैन; असली प्रश्न त विवाह वा सम्बन्धभित्र पसेपछि सुरु हुन्छ—के त्यो सम्बन्धमा दुवैको अस्तित्व, आवाज र मर्यादा बराबर छ?",
            paragraphs = listOf(
                "हाम्रो परम्परागत पारिवारिक ढाँचाले पति र पत्नीको सम्बन्धलाई प्रायः समान सहयात्रीका रूपमा भन्दा 'माथिल्लो र तल्लो' श्रेणीका रूपमा परिभाषित गर्यो। श्रीमान्लाई 'परमेश्वर' वा 'मालिक' को स्थान दिइयो र श्रीमतीलाई 'सेविका' वा 'अर्धाङ्गिनी' भनिए पनि व्यवहारमा दोस्रो दर्जाको नागरिक बनाइयो।",
